contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address target) internal {
        uint balBefore = address(c).balance;
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        try c.sendMoney(target, 0) {} catch { return; }
        assertTrue(address(c).balance == balBefore &&
            c.depositsCount() == countBefore &&
            c.owner() == ownerBefore);
    }

    function testFuzz_run(address target) public {
